import{_ as n,C as r,o as i,c as s,a2 as a,G as o}from"./chunks/framework.BgSoyxN5.js";const k=JSON.parse('{"title":"Market Intelligence | State Reads, Not A News Feed | TickerForge","description":"Market Regime, Market Stress, Fear & Greed, Sector Rotation and U.S. Economic Health — five recurring reads that tell you which market conditions you are in, not which headline just happened.","frontmatter":{"title":"Market Intelligence | State Reads, Not A News Feed | TickerForge","description":"Market Regime, Market Stress, Fear & Greed, Sector Rotation and U.S. Economic Health — five recurring reads that tell you which market conditions you are in, not which headline just happened.","aside":false,"locale":"en","alternateLocales":{"en":"/market-intelligence","ru":"/ru/market-intelligence"},"pageClass":"partners-page"},"headers":[],"relativePath":"market-intelligence/index.md","filePath":"market-intelligence/index.md","lastUpdated":1788187479000}'),l={name:"market-intelligence/index.md"};function h(d,e,c,p,m,g){const t=r("PartnerChannelCta");return i(),s("div",null,[e[0]||(e[0]=a('<h1 id="market-intelligence" tabindex="-1">Market Intelligence <a class="header-anchor" href="#market-intelligence" aria-label="Permalink to &quot;Market Intelligence&quot;">​</a></h1><p>Five recurring reads on the state of the market. Each one answers a question a news feed cannot.</p><p>A news feed gives you <strong>events</strong>. These give you a <strong>state</strong> — a named condition that persists for weeks, changes rarely, and is recorded every time it changes so you can check it later.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="/market-widget">See the live market read</a><a class="partners-button partners-button--secondary" href="/partners/market-news">Publish these in your channel</a></div><p class="partners-locale-switch"><a href="/ru/market-intelligence/" hreflang="ru">Читать эту страницу на русском</a></p><h2 id="the-difference-in-one-line" tabindex="-1">The Difference In One Line <a class="header-anchor" href="#the-difference-in-one-line" aria-label="Permalink to &quot;The Difference In One Line&quot;">​</a></h2><p>A headline tells you the S&amp;P fell 1% today. It cannot tell you whether that 1% is noise inside a trending market or confirmation inside a fragile one. That is the question these five reads exist to answer.</p><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format partners-format--linked"><span>Weekly and daily</span><strong><a href="/market-intelligence/market-regime">Market Regime</a></strong><p>Which of five conditions the market is in right now — and a separate alert on the days it actually changes.</p></div><div class="partners-format partners-format--linked"><span>Daily</span><strong><a href="/market-intelligence/market-stress">Market Stress</a></strong><p>Whether pressure across volatility, credit and rates is easing, mixed or rising.</p></div><div class="partners-format partners-format--linked"><span>Daily</span><strong><a href="/market-intelligence/fear-and-greed">Fear &amp; Greed</a></strong><p>Not just the sentiment level — the direction it is moving in, which is the half everyone else drops.</p></div><div class="partners-format partners-format--linked"><span>Daily and weekly</span><strong><a href="/market-intelligence/sector-rotation">Sector Rotation</a></strong><p>Which sectors actually lead, separated from the ones merely rising with the tide.</p></div><div class="partners-format partners-format--linked"><span>Monthly</span><strong><a href="/market-intelligence/economic-health">U.S. Economic Health</a></strong><p>One macro composite from 20+ indicators, with what is holding it up and what is dragging it down.</p></div></div></div><h2 id="why-these-are-not-signals" tabindex="-1">Why These Are Not Signals <a class="header-anchor" href="#why-these-are-not-signals" aria-label="Permalink to &quot;Why These Are Not Signals&quot;">​</a></h2><p>None of these tells anyone to buy or sell anything. They describe conditions. What a reader does inside those conditions is their own decision, and every post says so.</p><p>That is also why they can be checked. A channel that writes &quot;markets look volatile&quot; every week cannot be held to anything. A read that names a state, dates it, and only announces a change when the state actually changed, can.</p><h2 id="two-ways-to-use-them" tabindex="-1">Two Ways To Use Them <a class="header-anchor" href="#two-ways-to-use-them" aria-label="Permalink to &quot;Two Ways To Use Them&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Read them.</strong> All five run as automated programming on the TickerForge public channel, and each has its own card inside the bot.</li><li><strong>Publish them.</strong> An approved partner generates the same post with their own tracked link inside it, in English or Russian, in one tap. See <a href="/partners/market-news">Market News partners</a>.</li></ul></div>',13)),o(t),e[1]||(e[1]=a('<p>TickerForge is educational decision-support software. It is not financial advice, a signal channel, a broker, or a promise of investment results.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/market-widget">Live market regime widget</a></li><li><a href="/partners/market-news">Market news partner program</a></li><li><a href="/methodology/">Methodology index</a></li><li><a href="/pricing">TickerForge pricing</a></li></ul>',3))])}const u=n(l,[["render",h]]);export{k as __pageData,u as default};
